import sys

class Node:
    __slots__ = ('value', 'prev', 'next')
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    commands = input[1:n+1]

    head = None
    tail = None

    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            new_node.next = head
            if head is not None:
                head.prev = new_node
            head = new_node
            if tail is None:
                tail = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            found = False
            while current is not None:
                if current.value == x:
                    found = True
                    break
                current = current.next
            if found:
                prev_node = current.prev
                next_node = current.next
                if prev_node is not None:
                    prev_node.next = next_node
                else:
                    head = next_node
                if next_node is not None:
                    next_node.prev = prev_node
                else:
                    tail = prev_node
        elif parts[0] == 'deleteFirst':
            if head is not None:
                if head == tail:
                    head = tail = None
                else:
                    new_head = head.next
                    new_head.prev = None
                    head = new_head
        elif parts[0] == 'deleteLast':
            if tail is not None:
                if head == tail:
                    head = tail = None
                else:
                    new_tail = tail.prev
                    new_tail.next = None
                    tail = new_tail

    result = []
    current = head
    while current is not None:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

