    dp = [[0] * W for _ in range(H)]
    max_size = 0

    for i in range(H):
        for j in range(W):
            if matrix[i][j] == 0:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                if dp[i][j] > max_size:
                    max_size = dp[i][j]
            else:
                dp[i][j] = 0

    print(max_size * max_size)

if __name__ == "__main__":
    main()
